// Golden-vector tests for the payload v1 codec.
// vectors.hpp is GENERATED by ../tools/gen_vectors.py — the same bytes the
// TTN decoder, Android app and Flask server are validated against.

#include "vectors/vectors.hpp"

#include "testfw.hpp"

#include "domain/Payload.hpp"

using minilora::decodePayload;
using minilora::encodePayload;
using minilora::kPayloadSize;
using minilora::TelemetryData;
using minilora::vectors::GoldenVector;

static void encode_matches_golden(const GoldenVector &v)
{
    TelemetryData t{};
    t.tempC = static_cast<int8_t>(v.temp);
    t.humPct = static_cast<uint8_t>(v.hum);
    t.presDeciHpa = static_cast<uint16_t>(v.pres);
    t.batMv = v.bat_mv;
    t.lux = static_cast<uint16_t>(v.lux);
    for (int i = 0; i < 3; ++i) {
        t.acc[i] = static_cast<int16_t>(v.acc[i]);
    }
    t.latMicro = v.lat;
    t.lonMicro = v.lon;
    t.altM = static_cast<int16_t>(v.alt);
    t.sats = static_cast<uint8_t>(v.sat);
    t.epochSec = v.time;
    t.awakeSec = v.awake;
    t.sleepIdx = 0; // vectors store minutes; idx checked separately below
    t.gpioStatus = v.gpio;

    uint8_t out[minilora::kPayloadSize] = {};
    const size_t n = encodePayload(t, out);
    CHECK_EQ(n, kPayloadSize);
    for (size_t i = 0; i < kPayloadSize; ++i) {
        if (i == 26) {
            // byte 26 = sleep minutes; vectors encode minutes directly,
            // encoder derives them from sleepIdx.
            continue;
        }
        if (out[i] != v.frame[i]) {
            CHECK_EQ(out[i], v.frame[i]);
            return;
        }
    }
    CHECK(true);
}

static void test_encode_doc_example()
{
    encode_matches_golden(minilora::vectors::doc_example);
}

static void test_encode_negative_coords_night()
{
    encode_matches_golden(minilora::vectors::negative_coords_night);
}

static void test_encode_no_fix()
{
    encode_matches_golden(minilora::vectors::no_fix);
}

static void test_encode_edges()
{
    encode_matches_golden(minilora::vectors::edges);
}

static void test_encode_deep_winter()
{
    encode_matches_golden(minilora::vectors::deep_winter_long_sleep);
}

static void test_saturation_clamps_instead_of_wrapping()
{
    // v1 wrapped: (15000+10000)*255/20000 = 318 → (uint8_t)62
    CHECK_EQ(minilora::accelToByte(15000), 255);
    CHECK_EQ(minilora::accelToByte(-15000), 0);
    CHECK_EQ(minilora::batteryToByte(4500), 255);
    CHECK_EQ(minilora::batteryToByte(2000), 0);
    // Saturation is byte-exact with v1 inside the range:
    CHECK_EQ(minilora::accelToByte(0), 127);
    CHECK_EQ(minilora::accelToByte(10000), 255);
    CHECK_EQ(minilora::accelToByte(-10000), 0);
}

static void test_decode_roundtrip()
{
    const auto &v = minilora::vectors::negative_coords_night;
    TelemetryData t{};
    CHECK(decodePayload(v.frame, kPayloadSize, t));
    CHECK_EQ(static_cast<int>(t.tempC), v.temp);
    CHECK_EQ(t.latMicro, v.lat);
    CHECK_EQ(t.lonMicro, v.lon);
    CHECK_EQ(static_cast<int>(t.altM), v.alt);
    CHECK_EQ(t.batMv, static_cast<uint16_t>(v.bat_mv));
    for (int i = 0; i < 3; ++i) {
        // quantization: decoded raw is within 40 counts of original
        const int32_t diff = t.acc[i] - v.acc[i];
        CHECK(diff <= 80 && diff >= -80);
    }
}

static void test_decode_rejects_wrong_length()
{
    TelemetryData t{};
    uint8_t junk[27] = {};
    CHECK(!decodePayload(junk, sizeof(junk), t));
    CHECK(!decodePayload(nullptr, 0, t));
}

static void test_decode_doc_example_values()
{
    TelemetryData t{};
    CHECK(decodePayload(minilora::vectors::doc_example.frame, kPayloadSize, t));
    CHECK_EQ(static_cast<int>(t.tempC), 26);
    CHECK_EQ(static_cast<int>(t.humPct), 15);
    CHECK_EQ(static_cast<int>(t.presDeciHpa), 10170);
    CHECK_EQ(static_cast<int>(t.lux), 1071);
    CHECK_EQ(static_cast<int>(t.latMicro), 53069522);
    CHECK_EQ(static_cast<int>(t.lonMicro), 8879780);
    CHECK_EQ(static_cast<int>(t.altM), -3);
    CHECK_EQ(static_cast<int>(t.sats), 8);
    CHECK_EQ(static_cast<uint32_t>(t.epochSec), 1784486251u);
    CHECK_EQ(static_cast<int>(t.gpioStatus), 1);
}

static void test_sleep_index_roundtrip()
{
    for (uint8_t i = 0; i < minilora::kSleepTableLen; ++i) {
        CHECK_EQ(minilora::sleepIndexFromMinutes(minilora::sleepMinutes(i)), i);
    }
}

static void test_utc_to_epoch()
{
    // 2026-07-19 18:37:31 UTC == 1784486251 (golden vector time)
    CHECK_EQ(minilora::utcToEpoch(2026, 7, 19, 18, 37, 31), 1784486251u);
    // epoch 0
    CHECK_EQ(minilora::utcToEpoch(1970, 1, 1, 0, 0, 0), 0u);
    // leap year day (2024-02-29 = 1709164800)
    CHECK_EQ(minilora::utcToEpoch(2024, 2, 29, 0, 0, 0), 1709164800u);
}

void run_payload_tests()
{
    RUN(test_encode_doc_example);
    RUN(test_encode_negative_coords_night);
    RUN(test_encode_no_fix);
    RUN(test_encode_edges);
    RUN(test_encode_deep_winter);
    RUN(test_saturation_clamps_instead_of_wrapping);
    RUN(test_decode_roundtrip);
    RUN(test_decode_rejects_wrong_length);
    RUN(test_decode_doc_example_values);
    RUN(test_sleep_index_roundtrip);
    RUN(test_utc_to_epoch);
}
